const sourceMap = {"revision":"ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13","entries":{"uncertainty.py:propagate":{"file":"src/IDTIMS_UPbRPy/uncertainty.py","name":"propagate","line":10,"code":"def propagate(grain):\n    \"\"\"Propagate primitive errors once, preserving shared-variable covariance.\"\"\"\n    g = grain\n    names = [\"Pb_R65m\", \"Pb_R46m\", \"Pb_R76m\", \"Pb_R85m\", \"FPb\",\n             \"Pb_R65t\", \"Pb_R45t\", \"Pb_R76t\", \"Pb_R85t\",\n             \"R64b\", \"R76b\", \"R86b\", \"R64c\", \"R76c\", \"R84c\", \"Pb206b\",\n             \"U_R85m\", \"U_R35m\", \"U_R85t\", \"U_R35t\", \"U238b\"]\n    x = np.array([getattr(g, n) for n in names], dtype=float)\n    std = np.array([getattr(g, n + \"_std\") for n in names], dtype=float)\n    covariance = np.diag(std**2)\n    g.uncertainty_assumptions = []\n    def pair(a, b, cov):\n        i, j = names.index(a), names.index(b)\n        overrides = getattr(g, 'covariance_overrides', {})\n        cov = overrides.get((a,b), overrides.get((b,a), cov))\n        if abs(cov) > std[i]*std[j]*(1+1e-6):\n            if not getattr(g, 'strict_covariance', True):\n                message = f\"{g.id}: inconsistent uncertainties for {a}, {b}; their covariance is assumed zero (diagnostic approximation)\"\n                warnings.warn(message, RuntimeWarning, stacklevel=2)\n                g.uncertainty_assumptions.append(message)\n                cov = 0.0\n            else:\n                raise ValueError(f\"Grain {g.id}: impossible covariance for {a}, {b}\")\n        covariance[i, j] = covariance[j, i] = cov\n    pair(\"Pb_R65m\", \"Pb_R46m\", g.cov_65_46_m)\n    pair(\"Pb_R65m\", \"Pb_R76m\", g.cov_76_65_m)\n    pair(\"Pb_R65t\", \"Pb_R45t\", g.cov_45_65_t)\n    pair(\"Pb_R65t\", \"Pb_R76t\", g.cov_76_65_t)\n    pair(\"U_R85m\", \"U_R35m\", g.cov_85_35_m)\n    pair(\"U_R85t\", \"U_R35t\", g.cov_85_35_t)\n    # Ratios sharing 206Pb in the denominator are not independent of 206/204.\n    pair(\"R64b\", \"R76b\", g.R76b * (g.rho_6474_b*g.R64b_std*g.R74b_std/g.R74b - g.R64b_std**2/g.R64b))\n    pair(\"R64b\", \"R86b\", g.cov_86_64_b)\n    pair(\"R64c\", \"R76c\", g.R76c * (g.rho_6474_c*g.R64c_std*g.R74c_std/g.R74c - g.R64c_std**2/g.R64c))\n    # Complete missing three-ratio covariances by conditional independence.\n    # This is an explicit assumption, not a recovered Tripoli measurement.\n    for a,center,b in [('Pb_R46m','Pb_R65m','Pb_R76m'),\n                       ('Pb_R45t','Pb_R65t','Pb_R76t'),\n                       ('R76b','R64b','R86b')]:\n        i,j,k = (names.index(n) for n in (a,center,b))\n        covariance[i,k] = covariance[k,i] = covariance[i,j]*covariance[j,k]/covariance[j,j] if covariance[j,j] else 0.0\n        g.uncertainty_assumptions.append(f\"Cov({a},{b}) assumes conditional independence given {center}\")\n    # Measured 204/205 is represented here by (206/205)*(204/206).\n    # Retain the quotient-derived 208/205 versus 204/205 covariance by\n    # projecting it onto those primitives. Other links are completed by\n    # conditional independence given 204/205, rather than discarded.\n    for target, weights, cov in [\n        ('Pb_R85m', {'Pb_R65m': g.Pb_R46m, 'Pb_R46m': g.Pb_R65m}, g.cov_85_45_m),\n        ('Pb_R85t', {'Pb_R45t': 1.0}, g.cov_85_45_t),\n    ]:\n        gradient = np.zeros(len(names))\n        for name, weight in weights.items():\n            gradient[names.index(name)] = weight\n        q_cov = covariance @ gradient\n        variance = gradient @ q_cov\n        if variance > 0:\n            for j, name in enumerate(names):\n                if name != target:\n                    pair(target, name, cov*q_cov[j]/variance)\n        elif cov != 0:\n            raise ValueError(f\"Grain {g.id}: nonzero covariance with constant 204/205\")\n        g.uncertainty_assumptions.append(\n            f\"Cov({target},other Pb inputs) assumes conditional independence given 204/205; \"\n            \"derived 208/204 errors assume independent 208/205 and 204/205 unless overridden\")\n    for (a,b),cov in getattr(g,'covariance_overrides',{}).items():\n        pair(a,b,cov)\n    g.input_covariance = covariance\n    g.input_covariance_names = tuple(names)\n    g.input_values = x\n    active = std > 0\n    correlation = covariance[np.ix_(active,active)] / np.outer(std[active],std[active])\n    if not np.all(np.isfinite(correlation)) or (active.any() and np.linalg.eigvalsh(correlation).min() < -1e-6):\n        raise ValueError(f\"Grain {g.id}: input covariance is not positive semidefinite\")\n    output_names = [\"Pb206r\", \"Pb207r\", \"Pb208r\", \"U238s\", \"U235s\",\n                    \"R68r\", \"R75r\", \"R76r\", \"R86r\", \"R87r\"]\n    def evaluate(v):\n        (r65, r46, r76, r85, f, t65, t45, t76, t85,\n         b64, b76, b86, c64, c76, c84, b206,\n         u85, u35, ut85, ut35, ub) = v\n        c204 = (r65*r46*(1-f) - t45)*g.Pb205t - b206/b64\n        p206 = (r65*(1+f)-t65)*g.Pb205t - b206 - c64*c204\n        p207 = (r65*r76*(1+2*f)-t65*t76)*g.Pb205t - b76*b206 - c64*c76*c204\n        p208 = (r85*(1+3*f)-t85)*g.Pb205t - b86*b206 - c84*c204\n        u = g.common_U238_U235\n        fu = (ut35*(u-u85)+u35*(ut85-u))/(2*u35*(ut85-u)+3*ut35*u85)\n        u238 = (g.U235t*u85*(1+3*fu)-ut85*g.U235t-ub)/(1-u85/u*(1+3*fu))\n        u235 = u238/u\n        return np.array([p206, p207, p208, u238, u235,\n                         p206/u238, p207/u235, p207/p206, u238/p206, u238/p207])\n    # Complex-step differentiation avoids subtractive cancellation at mol scale.\n    jacobian = np.empty((len(output_names), len(x)))\n    for i in range(len(x)):\n        v = x.astype(complex)\n        v[i] += 1e-30j\n        jacobian[:, i] = evaluate(v).imag / 1e-30\n    result = jacobian @ covariance @ jacobian.T\n    diagonal = np.diag(result)\n    if np.any(diagonal < 0) or not np.all(np.isfinite(result)):\n        raise ValueError(f\"Grain {g.id}: inconsistent input covariance produces invalid variance\")\n    for name, error in zip(output_names, np.sqrt(diagonal)):\n        setattr(g, name + \"_std\", float(error))\n    g.reduction_covariance = result\n    g.reduction_covariance_names = tuple(output_names)\n    def rho(a, b):\n        i, j = output_names.index(a), output_names.index(b)\n        denom = np.sqrt(result[i, i]*result[j, j])\n        value = result[i, j]/denom if denom else 0.0\n        if abs(value) > 1 + 1e-8:\n            raise ValueError(f\"Grain {g.id}: invalid propagated correlation {a}, {b}\")\n        return float(np.clip(value, -1, 1))\n    g.rho_7568_r = rho(\"R75r\", \"R68r\")\n    g.rho_8676_r = rho(\"R86r\", \"R76r\")\n    g.cov_R76r = result[0, 1]","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/uncertainty.py#L10"},"uncertainty.py:propagate_th":{"file":"src/IDTIMS_UPbRPy/uncertainty.py","name":"propagate_th","line":125,"code":"def propagate_th(grain):\n    \"\"\"Propagate the correction through Pb and U jointly, including covariance.\"\"\"\n    from .utils import calc_t68_Th\n    g = grain\n    indices = [0,1,2,3]  # Pb206r, Pb207r, Pb208r, U238s\n    cov = np.zeros((5,5))\n    cov[:4,:4] = g.reduction_covariance[np.ix_(indices,indices)]\n    parameter = g.D_Th_U if g.Th230_correction_type == 'D' else g.Th_U_magma\n    error = g.D_Th_U_std if g.Th230_correction_type == 'D' else g.Th_U_magma_std\n    cov[4,4] = error**2\n    x = np.array([g.Pb206r,g.Pb207r,g.Pb208r,g.U238s,parameter])\n    def evaluate(v):\n        p206,p207,p208,u238,param = v\n        if g.Th230_correction_type == 'D':\n            corrected = p206/u238 + g.lambda_238/g.lambda_230*(1-param)\n        else:\n            t = calc_t68_Th(p206/u238,type='magma',Pb208r=p208,U238s=u238,\n                Th_U_magma=param,lambda_238=g.lambda_238,lambda_230=g.lambda_230,\n                lambda_232=g.lambda_232)\n            corrected = np.expm1(g.lambda_238*t*1e6)\n        return np.array([corrected,p207/(u238*corrected)])\n    jacobian = np.zeros((2,5))\n    for i in range(5):\n        if g.Th230_correction_type == 'D':\n            v = x.astype(complex)\n            v[i] += 1e-30j\n            jacobian[:,i] = evaluate(v).imag/1e-30\n        else:\n            step = max(abs(x[i])*1e-4,1e-25)\n            hi,lo = x.copy(),x.copy()\n            hi[i] += step\n            lo[i] -= step\n            jacobian[:,i] = (evaluate(hi)-evaluate(lo))/(2*step)\n    corrected_cov = jacobian @ cov @ jacobian.T\n    if np.any(np.diag(corrected_cov) < 0):\n        raise ValueError(f\"Grain {g.id}: invalid Th correction variance\")\n    g.R68r_Th_std,g.R76r_Th_std = np.sqrt(np.diag(corrected_cov))\n    g.th_correction_covariance = corrected_cov","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/uncertainty.py#L125"},"quality.py:check_ratio_errors":{"file":"src/IDTIMS_UPbRPy/quality.py","name":"check_ratio_errors","line":30,"code":"def check_ratio_errors(x_error_pct, u_error_pct, v_error_pct, *,\n                       relationship='product', grain=None, identity='', tolerance=1e-6):\n    \"\"\"Infer Corr(u,v) from errors in x=u*v or x=u/v.\n\n    Relative errors may share any common unit or sigma level (the report\n    labels them percent). Never clips an invalid inferred correlation.\n    Correlation is undefined when either component error is zero; the error\n    identity is still checked. Tolerance applies to correlation bounds.\n    \"\"\"\n    sx, su, sv = map(float, (x_error_pct, u_error_pct, v_error_pct))\n    if any(not math.isfinite(s) or s < 0 for s in (sx, su, sv)):\n        raise ValueError(f'Grain {grain}: relative errors must be finite and nonnegative')\n    if relationship not in ('product', 'quotient'):\n        raise ValueError('relationship must be product or quotient')\n    if not math.isfinite(tolerance) or tolerance < 0:\n        raise ValueError('tolerance must be finite and nonnegative')\n    # Scale before squaring to avoid overflow/underflow and ensure the\n    # consistency decision is independent of the supplied error units.\n    scale = max(sx, su, sv)\n    x, u, v = (s/scale for s in (sx, su, sv)) if scale else (0.0, 0.0, 0.0)\n    if u and v:\n        rho = (x*x-u*u-v*v)/(2*u*v)\n        if relationship == 'quotient':\n            rho = -rho\n        passed = abs(rho) <= 1+tolerance\n        status = 'pass' if passed else 'fail'\n    else:\n        rho = None\n        passed = abs(x*x-u*u-v*v) <= tolerance*max(x*x, u*u+v*v)\n        status = 'undefined' if passed else 'fail'\n    return dict(grain=grain, identity=identity, relationship=relationship,\n                implied_correlation=rho, passed=passed, status=status,\n                x_error_pct=sx, u_error_pct=su, v_error_pct=sv,\n                x_error_lower_pct=abs(su-sv), x_error_upper_pct=su+sv)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/quality.py#L30"},"utils.py:Pb206s_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb206s_partials","line":271,"code":"def Pb206s_partials(R65m, FPb, Pb205t):\n    return {\n        \"dPb206s_dR65m\": (1 + FPb) * Pb205t,\n        \"dPb206s_dR65t\": -Pb205t,\n        \"dPb206s_dFPb\": R65m * Pb205t,\n        \"dPb206s_dPb206b\": -1.0,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L271"},"utils.py:Pb206r_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb206r_partials","line":279,"code":"def Pb206r_partials(R65m, R46m, \n                    FPb, \n                    Pb205t, \n                    R45t,\n                    R64b,  Pb206b,\n                    R64c, \n):\n    return {\"dPb206r_dR65m\": ((1 + FPb) - R64c * R46m * (1 - FPb)) * Pb205t,\n            \"dPb206r_dR46m\": -R65m * R64c * (1 - FPb) * Pb205t,\n            \"dPb206r_dR65t\": -Pb205t,\n            \"dPb206r_dR45t\": R64c * Pb205t,\n            \"dPb206r_dFPb\": (1 + R64c * R46m) * R65m * Pb205t,\n            \"dPb206r_dPb206b\": R64c/R64b-1.0,\n            \"dPb206r_dR64b\": -Pb206b * R64c / R64b**2,\n            \"dPb206r_dR64c\": (-R46m * R65m * Pb205t * ( 1 - FPb)) + (R45t * Pb205t) + Pb206b/R64b}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L279"},"utils.py:Pb207s_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb207s_partials","line":295,"code":"def Pb207s_partials(R65m, R76m, \n                    FPb, \n                    Pb205t, \n                    R65t, \n                    R76t, \n                    R76b, \n                    Pb206b):\n    return {\n        \"dPb207s_dR65m\": R76m * (1 + 2 * FPb) * Pb205t,\n        \"dPb207s_dR76m\": R65m * (1 + 2 * FPb) * Pb205t,\n        \"dPb207s_dFPb\": 2 * R65m * R76m * Pb205t,\n        \"dPb207s_dR65t\": -R76t * Pb205t,\n        \"dPb207s_dR76t\": -R65t * Pb205t,\n        \"dPb207s_dPb206b\": -R76b,\n        \"dPb207s_dR76b\": -Pb206b,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L295"},"utils.py:Pb207r_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb207r_partials","line":312,"code":"def Pb207r_partials(R65m, R76m, R46m,\n                    FPb, \n                    Pb205t, \n                    R45t,\n                    R65t, \n                    R76t, \n                    R76b, \n                    R64b,\n                    Pb206b, \n                    R64c,\n                    R76c):\n    return {\"dPb207r_dR65m\": (R76m * (1 + 2 * FPb) - R64c * R76c * R46m * ( 1 - FPb)) * Pb205t,\n            \"dPb207r_dR76m\": R65m * (1 + 2 * FPb) * Pb205t,\n            \"dPb207r_dR46m\": -R64c * R76c * R65m * (1 - FPb) * Pb205t,\n            \"dPb207r_dFPb\": (2 * R76m + R64c * R76c * R46m) * R65m * Pb205t,\n\n            \"dPb207r_dR65t\": -R76t * Pb205t,\n            \"dPb207r_dR76t\": -R65t * Pb205t,\n            \"dPb207r_dR45t\": R64c * R76c * Pb205t,\n            \"dPb207r_dPb206b\": -R76b + R64c * R76c / R64b,\n            \"dPb207r_dR64b\": -Pb206b * R64c * R76c / R64b **2,\n            \"dPb207r_dR76b\": -Pb206b,\n            \"dPb207r_dR64c\": (-R46m * R65m * Pb205t * R76c * (1 - FPb)) + (R45t * R76c * Pb205t) + (Pb206b * R76c / R64b),\n            \"dPb207r_dR76c\": (-R46m * R65m * Pb205t * R64c * (1 - FPb)) + (R45t * R64c * Pb205t) + (Pb206b * R64c / R64b),}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L312"},"utils.py:Pb204c_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb204c_partials","line":337,"code":"def Pb204c_partials(R46m, R65m, \n                    FPb, \n                    Pb205t, \n                    R46t, \n                    R65t, \n                    Pb206b, \n                    R64b):\n    return {\n        \"dPb204c_dR46m\": R65m * (1 - FPb) * Pb205t,\n        \"dPb204c_dR65m\": R46m * (1 - FPb) * Pb205t,\n        \"dPb204c_dFPb\": -R46m * R65m * Pb205t,\n        \"dPb204c_dR46t\": -R65t * Pb205t,\n        \"dPb204c_dR65t\": -R46t * Pb205t,\n        \"dPb204c_dPb206b\": -1.0 / R64b,\n        \"dPb204c_dR64b\": Pb206b / R64b**2,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L337"},"utils.py:FU_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"FU_partials","line":354,"code":"def FU_partials(R35m, R85m,\n                R35t, R85t,\n                common_U238_U235=common_U238_U235):\n    \n    denom = 2 * R35m * (R85t - common_U238_U235) + 3 * R35t * R85m\n\n    return {\n        \"dFU_dR35t\": (common_U238_U235 - R85m) / denom - (3 * R85m * (R35t * (common_U238_U235 - R85m) + R35m * (R85t - common_U238_U235))) / denom**2,\n        \"dFU_dR85m\": -R35t / denom - (3 * R35t * (R35t * (common_U238_U235 - R85m) + R35m * (R85t - common_U238_U235))) / denom**2,\n        \"dFU_dR35m\": (R85t - common_U238_U235) / denom - (2 * (R85t - common_U238_U235) * (R35t * (common_U238_U235 - R85m) + R35m * (R85t - common_U238_U235))) / denom**2,\n        \"dFU_dR85t\": R35m / denom - (2 * R35m * (R35t * (common_U238_U235 - R85m) + R35m * (R85t - common_U238_U235))) / denom**2,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L354"},"utils.py:U238s_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"U238s_partials","line":367,"code":"def U238s_partials(R85m, FU, U235t, R85t, U238b, common_U238_U235=common_U238_U235):\n    denom = 1 - R85m / common_U238_U235 * (1 + 3 * FU)\n    numer = U235t * R85m * (1 + 3 * FU) - (R85t * U235t) - U238b\n    return {\n        \"dU238s_dR85m\": (U235t * (1 + 3 * FU)) / denom + numer / denom**2 * (1 + 3 * FU) / common_U238_U235,\n        \"dU238s_dR85t\": -U235t / denom,\n        \"dU238s_dU238b\": -1 / denom,\n        \"dU238s_dFU\": (3 * U235t * R85m) / denom + numer / denom**2 * (3 * R85m) / common_U238_U235,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L367"},"utils.py:U235s_partials":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"U235s_partials","line":377,"code":"def U235s_partials(common_U238_U235=common_U238_U235):\n    return {\n        \"dU235s_dU238s\": 1 / common_U238_U235,\n    }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L377"},"utils.py:Pb_covariance_squared":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"Pb_covariance_squared","line":382,"code":"def Pb_covariance_squared(R75m, R75m_std, \n                          R76m, R76m_std, \n                          R65m, R65m_std, \n                          R45m, R45m_std,\n                          R46m, R46m_std,\n                          R84m, R84m_std,\n                          R85m, R85m_std,\n                          R75t, R75t_std,\n                          R76t, R76t_std,\n                          R65t, R65t_std,\n                          R45t, R45t_std,\n                          R46t, R46t_std,\n                          R84t, R84t_std,\n                          R85t, R85t_std,\n                          R64b, R64b_std,\n                          R84b, R84b_std,\n                          R86b, R86b_std):\n    return {\"cov_76_65_m\": calc_covariance_squared(R75m, R75m_std, R76m, R76m_std, R65m, R65m_std, type='product'),\n            \"cov_76_65_t\": calc_covariance_squared(R75t, R75t_std, R76t, R76t_std, R65t, R65t_std, type='product'),\n            \"cov_65_46_m\": calc_covariance_squared(R45m, R45m_std, R65m, R65m_std, R46m, R46m_std, type='product'),\n            \"cov_45_65_t\": calc_covariance_squared(R46t, R46t_std, R45t, R45t_std, R65t, R65t_std,  type='quotient'),\n            \"cov_65_46_t\": calc_covariance_squared(R45t, R45t_std, R65t, R65t_std, R46t, R46t_std, type='product'),\n            \"cov_85_45_m\": calc_covariance_squared(R84m, R84m_std, R85m, R85m_std, R45m, R45m_std, type='quotient'),\n            \"cov_85_45_t\": calc_covariance_squared(R84t, R84t_std, R85t, R85t_std, R45t, R45t_std, type='quotient'),\n            \"cov_86_64_b\": calc_covariance_squared(R84b, R84b_std, R86b, R86b_std, R64b, R64b_std, type='product')\n            }","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L382"},"utils.py:U_covariance_squared":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"U_covariance_squared","line":409,"code":"def U_covariance_squared(R83m, R83m_std,\n                         R85m, R85m_std,\n                         R35m, R35m_std,\n                         R83t, R83t_std,\n                         R85t, R85t_std,\n                         R35t, R35t_std):\n        return {\"cov_85_35_m\": calc_covariance_squared(R83m, R83m_std, R85m, R85m_std, R35m, R35m_std, type='quotient'),\n                \"cov_85_35_t\": calc_covariance_squared(R83t, R83t_std, R85t, R85t_std, R35t, R35t_std, type='quotient')}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L409"},"utils.py:calc_Pb206s":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_Pb206s","line":420,"code":"def calc_Pb206s(R65m, FPb, \n                Pb205t, \n                R65t, \n                Pb206b):\n    \"\"\"\n    Calculate measured 206Pb in sample (Pb206s)\n\n    Parameters\n    ----------\n    R65m : float\n        Measured total 206Pb/205Pb ratio\n    Pb205t : float\n        Tracer solution 205Pb amount (moles_g)\n    FPb : float\n        Coefficient for linear Pb fractionation correction per unit mass difference\n    R65t : float\n        Tracer solution 206Pb/205Pb ratio\n    Pb206b : float\n        Blank 206Pb amount (moles_g)\n    \"\"\"\n    Pb206s = R65m * Pb205t * (1 + FPb) - R65t * Pb205t - Pb206b\n    return Pb206s","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L420"},"utils.py:calc_Pb207s":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_Pb207s","line":490,"code":"def calc_Pb207s(R65m, R76m, \n                FPb, \n                Pb205t, R65t, R76t, \n                R76b, Pb206b):\n    \"\"\"\n    Calculate measured 207Pb in sample (Pb207s)\n\n    Parameters\n    ----------\n    R65m : float\n        Measured total 206Pb/205Pb ratio\n    R76m : float\n        Measured total 207Pb/206Pb ratio\n    FPb : float\n        Coefficient for linear Pb fractionation correction per unit mass difference\n    Pb205t : float\n        Tracer solution 205Pb amount (moles_g)\n    R65t : float\n        Tracer solution 206Pb/205Pb ratio\n    R76t : float\n        Tracer solution 207Pb/206Pb ratio\n    R76b : float\n        Blank 207Pb/206Pb ratio\n    Pb206b : float\n        Blank 206Pb amount (moles_g)\n    \"\"\"\n    Pb207s = R65m * R76m * Pb205t * (1 + 2 * FPb) - R65t * R76t * Pb205t - R76b * Pb206b\n    return Pb207s","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L490"},"utils.py:calc_Pb204c":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_Pb204c","line":612,"code":"def calc_Pb204c(R46m, R65m, \n               FPb, \n               Pb205t, R46t, R65t, \n               Pb206b, R64b):\n    \"\"\"\n    Calculate initial 204Pb in sample (Pb204c)\n\n    Parameters\n    ----------\n    R46m : float\n        Measured total 204Pb/206Pb ratio\n    R65m : float\n        Measured total 206Pb/205Pb ratio\n    FPb : float\n        Coefficient for linear Pb fractionation correction per unit mass difference\n    Pb205t : float\n        Tracer solution 205Pb amount (moles_g)\n    R46t : float\n        Tracer solution 204Pb/206Pb ratio\n    R65t : float\n        Tracer solution 206Pb/205Pb ratio\n    Pb206b : float\n        Blank 206Pb amount (moles_g)\n    R64b : float\n        Blank 204Pb/206Pb ratio\n    \"\"\"\n    Pb204c = R46m * R65m * Pb205t * (1 - FPb) - R46t * R65t * Pb205t - Pb206b / R64b\n    return Pb204c","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L612"},"utils.py:calc_FU":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_FU","line":733,"code":"def calc_FU(R35m, R85m,\n            R35t, R85t, \n           common_U238_U235=common_U238_U235):\n    \"\"\"\n    Calculate U fractionation factor F_U\n\n    Parameters\n    ----------\n    R35t : float\n        Tracer solution 235U/238U ratio\n    R35m : float\n        Measured total 235U/238U ratio\n    R85t : float\n        Tracer solution 238U/235U ratio\n    R85m : float\n        Measured total 238U/235U ratio\n    \"\"\"\n    FU = (R35t * (common_U238_U235 - R85m) + R35m * (R85t - common_U238_U235)) / (2 * R35m * (R85t - common_U238_U235) + 3 * R35t * R85m)\n    return FU","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L733"},"utils.py:calc_U235s":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_U235s","line":898,"code":"def calc_U235s(U238s, common_U238_U235=common_U238_U235):\n    \"\"\"\n    Calculate measured 235U in sample (U235s)\n\n    Parameters\n    ----------\n    U238s : float\n        Measured 238U in sample (moles_g)\n    common_U238_U235 : float, optional\n        Natural 238U/235U ratio, by default common_U238_U235\n    \"\"\"\n    U235s = U238s / common_U238_U235\n    return U235s","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L898"},"utils.py:calc_PbPb_Rs":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_PbPb_Rs","line":953,"code":"def calc_PbPb_Rs(Pb206s, Pb207s, Pb204c):\n    \"\"\"\n    Calculate sample Pb-Pb ratios\n\n    Parameters\n    ----------\n    Pb206s : float\n        Measured 206Pb in sample (moles)\n    Pb207s : float\n        Measured 207Pb in sample (moles)\n    Pb204c : float\n        Initial 204Pb in sample (moles)\n    \"\"\"\n    if Pb204c > 0:\n        return {\"R46s\": Pb204c / Pb206s,\n                \"R47s\": Pb204c / Pb207s,\n                \"R74s\": Pb207s / Pb204c,\n                \"R76s\": Pb207s / Pb206s}\n    elif Pb204c == 0:\n        return {\"R46s\": Pb204c / Pb206s,\n                \"R47s\": Pb204c / Pb207s,\n                \"R74s\": 0.0,\n                \"R76s\": Pb207s / Pb206s}\n    else:\n        raise ValueError(\"Pb204c must be non-negative\")","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L953"},"utils.py:calc_UPb_Rs":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_UPb_Rs","line":979,"code":"def calc_UPb_Rs(U238s, U235s, Pb206s, Pb207s, Pb204c):\n    \"\"\"\n    calculate sample U-Pb ratios\n\n    Parameters\n    ----------\n    U238s : float\n        Measured 238U in sample (moles)\n    U235s : float\n        Measured 235U in sample (moles)   \n    Pb206s : float\n        Measured 206Pb in sample (moles)\n    Pb207s : float\n        Measured 207Pb in sample (moles)\n    Pb204c : float\n        Initial 204Pb in sample (moles)\n    \"\"\"\n    if Pb204c > 0:\n        return {\"R54s\": U235s / Pb204c,\n                \"R57s\": U235s / Pb207s,\n                \"R84s\": U238s / Pb204c,\n                \"R86s\": U238s / Pb206s,\n                \"R87s\": U238s / Pb207s}\n    elif Pb204c == 0:\n        return {\"R54s\": 0.0,\n                \"R57s\": U235s / Pb207s,\n                \"R84s\": 0.0,\n                \"R86s\": U238s / Pb206s,\n                \"R87s\": U238s / Pb207s}\n    else:\n        raise ValueError(\"Pb204c must be non-negative\")","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L979"},"utils.py:calc_UPb_Rr":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_UPb_Rr","line":1014,"code":"def calc_UPb_Rr(U238s, U235s, Pb206r, Pb207r):\n    '''\n    calculate radiogenic U-Pb ratios with the assumption that all U measured is from the sample\n\n    Parameters\n    ----------\n    U238s : float\n        Measured 238U in sample (moles)\n    U235s : float\n        Measured 235U in sample (moles)   \n    Pb206r : float\n        Radiogenic 206Pb in sample (moles)\n    Pb207r : float\n        Radiogenic 207Pb in sample (moles)\n    '''\n    return {\"R68r\": Pb206r / U238s,\n            \"R86r\": U238s / Pb206r,\n            \"R75r\": Pb207r / U235s,\n            \"R87r\": U238s / Pb207r}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1014"},"utils.py:calc_PbPb_uncertainty":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_PbPb_uncertainty","line":1101,"code":"def calc_PbPb_uncertainty(Pb20X, Pb20Y, Pb20X_std, Pb20Y_std, cov_Pb_RXY_squared):\n    '''\n    calculate relative and absolute uncertainty of a Pb isotope ratio\n    applies to both sample total Pb-Pb ratios and radiogenic Pb-Pb ratios\n\n    Parameters\n    ----------\n    Pb20X : float\n        Measured 20X Pb isotope in sample (moles_g)\n    Pb20Y : float\n        Measured 20Y Pb isotope in sample (moles_g)\n    Pb20X_std : float\n        Standard deviation of measured 20X Pb isotope in sample (moles_g)\n    Pb20Y_std : float\n        Standard deviation of measured 20Y Pb isotope in sample (moles_g)\n    cov_Pb_RXY_squared : float\n        Covariance squared between Pb20X and Pb20Y\n    '''\n    if Pb20X > 0 and Pb20Y > 0:\n        rel_std_Pb_RXY = np.sqrt( (Pb20X_std / Pb20X) ** 2 + (Pb20Y_std / Pb20Y) ** 2 - 2 * cov_Pb_RXY_squared / (Pb20X * Pb20Y) )\n\n        abs_std_Pb_RXY = Pb20X / Pb20Y * rel_std_Pb_RXY\n\n    else:\n        rel_std_Pb_RXY = 0.0\n        abs_std_Pb_RXY = 0.0\n\n    return {\"rel_std\": rel_std_Pb_RXY,\n            \"abs_std\": abs_std_Pb_RXY}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1101"},"utils.py:calc_PbPbs_rhos":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_PbPbs_rhos","line":1157,"code":"def calc_PbPbs_rhos(R74s, R74s_std,\n                   R64s, R64s_std,\n                   R76s, R76s_std,\n                   R46s, R46s_std):\n    '''\n    Calculate correlation coefficients (rhos) between Pb-Pb isotope ratios\n\n    Parameters\n    ----------\n    R74s : float\n        Sample 207Pb/204Pb ratio\n    R74s_std : float\n        Absolute standard deviation of sample 207Pb/204Pb ratio\n    R64s : float\n        Sample 206Pb/204Pb ratio\n    R64s_std : float\n        Absolute standard deviation of sample 206Pb/204Pb ratio\n    R76s : float\n        Sample 207Pb/206Pb ratio\n    R76s_std : float\n        Absolute standard deviation of sample 207Pb/206Pb ratio\n    R46s : float\n        Sample 204Pb/206Pb ratio\n    R46s_std : float\n        Absolute standard deviation of sample 204Pb/206Pb ratio\n    '''\n\n    rho_7464_s = calc_rho_quotient(R76s, R76s_std,\n                                 R74s, R74s_std,\n                                 R64s, R64s_std)\n    \n    rho_7646_s = calc_rho_quotient(R74s, R74s_std,\n                                 R76s, R76s_std,\n                                 R46s, R46s_std)\n    \n    return {\"rho_7464_s\": rho_7464_s,\n            \"rho_7646_s\": rho_7646_s}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1157"},"utils.py:calc_UPbs_rhos":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_UPbs_rhos","line":1195,"code":"def calc_UPbs_rhos(R64s, R64s_std,\n                  R74s, R74s_std,\n                  R76s, R76s_std,\n                  R46s, R46s_std,\n                  R84s, R84s_std, \n                  R54s, R54s_std,\n                  R57s, R57s_std,\n                  R86s, R86s_std,\n                  R87s, R87s_std):\n    '''\n    Calculate correlation coefficients (rhos) between sample total U-Pb isotope ratios\n\n    Parameters\n    ----------\n    R64s : float\n        Sample 206Pb/204Pb ratio\n    R64s_std : float\n        Absolute standard deviation of sample 206Pb/204Pb ratio\n    R74s : float\n        Sample 207Pb/204Pb ratio\n    R74s_std : float\n        Absolute standard deviation of sample 207Pb/204Pb ratio\n    R76s : float\n        Sample 207Pb/206Pb ratio\n    R76s_std : float\n        Absolute standard deviation of sample 207Pb/206Pb ratio\n    R46s : float\n        Sample 204Pb/206Pb ratio\n    R46s_std : float\n        Absolute standard deviation of sample 204Pb/206Pb ratio\n    R84s : float\n        Sample 238U/204Pb ratio\n    R84s_std : float\n        Absolute standard deviation of sample 238U/204Pb ratio\n    R54s : float\n        Sample 235U/204Pb ratio\n    R54s_std : float\n        Absolute standard deviation of sample 235U/204Pb ratio\n    R86s : float\n        Sample 238U/206Pb ratio\n    R86s_std : float\n        Absolute standard deviation of sample 238U/206Pb ratio\n    '''\n\n    rho_8464_s = calc_rho_quotient(R86s, R86s_std,\n                                 R84s, R84s_std,\n                                 R64s, R64s_std)\n    \n    rho_5474_s = calc_rho_quotient(R57s, R57s_std,\n                                 R54s, R54s_std,\n                                 R74s, R74s_std)\n    \n    rho_8676_s = calc_rho_quotient(R87s, R87s_std,\n                                 R86s, R86s_std,\n                                 R76s, R76s_std)\n    \n    rho_8646_s = calc_rho_quotient(R84s, R84s_std,\n                                 R86s, R86s_std,\n                                 R46s, R46s_std)\n    \n    return {\"rho_8464_s\": rho_8464_s,\n            \"rho_5474_s\": rho_5474_s,\n            \"rho_8676_s\": rho_8676_s,\n            \"rho_8646_s\": rho_8646_s}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1195"},"utils.py:calc_Pb206r":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_Pb206r","line":1260,"code":"def calc_Pb206r(R65m, R46m,\n                FPb,\n                Pb205t,\n                R65t,\n                R45t,\n                R64c,\n                R64b,\n                Pb206b):\n    '''\n    calculate radiogenic 206Pb in sample (Pb206r)\n\n    Parameters\n    ----------\n    R65m : float\n        Measured total 206Pb/205Pb ratio\n    R46m : float\n        Measured total 204Pb/206Pb ratio\n    FPb : float\n        Coefficient for linear Pb fractionation correction per unit mass difference\n    Pb205t : float\n        Tracer solution 205Pb amount (moles)\n    R65t : float\n        Tracer solution 206Pb/205Pb ratio\n    R45t : float\n        Tracer solution 204Pb/205Pb ratio\n    R64c : float\n        Initial 204Pb/206Pb ratio in sample\n    R64b : float\n        Blank 204Pb/206Pb ratio\n    Pb206b : float\n        Blank 206Pb amount (moles)\n    '''\n    return R65m * Pb205t * (1 + FPb) - (R65t * Pb205t) - Pb206b - R64c * (R46m * R65m * Pb205t * ( 1 - FPb) - R45t * Pb205t - Pb206b/R64b)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1260"},"utils.py:calc_Pb207r":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_Pb207r","line":1345,"code":"def calc_Pb207r(R65m, R76m, R46m,\n                FPb,\n                Pb205t,\n                R65t,\n                R76t,\n                R45t,\n                R76c,\n                R64c,\n                R64b,\n                R76b,\n                Pb206b):\n    return (R65m * R76m * (1 + 2 * FPb) - R65t * R76t) * Pb205t - (R76b * Pb206b) - R64c * R76c * (R46m * R65m * Pb205t * (1 - FPb) - R45t * Pb205t - Pb206b / R64b)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1345"},"utils.py:calc_UPbr_rhos":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_UPbr_rhos","line":1487,"code":"def calc_UPbr_rhos(R75r, R75r_std,\n                   R68r, R68r_std,\n                   R76r, R76r_std,\n                   R86r, R86r_std,\n                   R87r, R87r_std):\n    '''\n    Calculate correlation coefficients (rhos) between radiogenic U-Pb radiogenic isotope ratios\n\n    Parameters\n    ----------\n    R75r : float\n        Radiogenic 207Pb/235U ratio\n    R75r_std : float\n        Absolute standard deviation of radiogenic 207Pb/235U ratio\n    R68r : float\n        Radiogenic 206Pb/238U ratio\n    R68r_std : float\n        Absolute standard deviation of radiogenic 206Pb/238U ratio\n    R76r : float\n        Radiogenic 207Pb/206Pb ratio\n    R76r_std : float\n        Absolute standard deviation of radiogenic 207Pb/206Pb ratio\n    R86r : float\n        Radiogenic 238U/206Pb ratio\n    R86r_std : float\n        Absolute standard deviation of radiogenic 238U/206Pb ratio\n    R87r : float\n        Radiogenic 238U/207Pb ratio\n    R87r_std : float\n        Absolute standard deviation of radiogenic 238U/207Pb ratio\n    '''\n    rho_7568_r = calc_rho_quotient(R76r, R76r_std,\n                                 R75r, R75r_std,\n                                 R68r, R68r_std)\n    rho_8676_r = calc_rho_quotient(R87r, R87r_std,\n                                 R86r, R86r_std,\n                                 R76r, R76r_std)\n    \n    return {\"rho_7568_r\": rho_7568_r,\n            \"rho_8676_r\": rho_8676_r}","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1487"},"utils.py:calc_t76":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_t76","line":1547,"code":"def calc_t76(ratio,x0=1e6, tol=1e-8, \n                 lambda_235=lambda_235, lambda_238=lambda_238, \n                 common_U238_U235=common_U238_U235):\n    '''\n    calculates 207Pb/206Pb date given a 207Pb/206Pb ratio\n    \n    do not take a list of values\n    \n    Required Parameters:\n    ---------------------\n    ratio: the measured 76 ratio\n    \n    Optional Parameters:\n    ---------------------\n    x0: historical initial guess in years, accepted and ignored\n    tol: root tolerance in years\n    \n    Return:\n    ---------------------\n    age in Ma\n    \n    '''\n    if not np.isfinite(ratio) or tol <= 0 or not np.isfinite(tol):\n        raise ValueError(\"Ratio must be finite and tolerance positive\")\n    if not (lambda_235 > lambda_238 > 0 and common_U238_U235 > 0):\n        raise ValueError(\"Require lambda_235 > lambda_238 > 0 and positive U ratio\")\n    def ratio_diff(t):\n        return _pb76_ratio(t, lambda_235, lambda_238, common_U238_U235) - ratio\n    if ratio_diff(0) > 0 or ratio_diff(4600) < 0:\n        raise ValueError(\"207Pb/206Pb ratio has no age in the supported 0–4600 Ma interval\")\n    return brentq(ratio_diff, 0, 4600, xtol=tol / 1e6, rtol=4*np.finfo(float).eps)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1547"},"utils.py:calc_t68_uncertainty":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_t68_uncertainty","line":1586,"code":"def calc_t68_uncertainty(R68r, R68r_std, lambda_238=lambda_238):\n    '''\n    calculate 206Pb/238U date uncertainty\n\n    Parameters\n    ----------\n    R68r : float\n        Radiogenic 206Pb/238U ratio\n    R68r_std : float\n        Absolute standard deviation of radiogenic 206Pb/238U ratio\n\n    Returns\n    -------\n    68 age uncertainty in Ma\n    '''\n    if np.any(~np.isfinite(R68r)) or np.any(np.asarray(R68r) < 0) or np.any(~np.isfinite(R68r_std)) or np.any(np.asarray(R68r_std) < 0) or not (np.isfinite(lambda_238) and lambda_238 > 0):\n        raise ValueError(\"Invalid ratio, uncertainty or decay constant\")\n    return 1 / lambda_238 * ( R68r_std / (R68r + 1) ) / 1e6","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1586"},"utils.py:calc_t75_uncertainty":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_t75_uncertainty","line":1605,"code":"def calc_t75_uncertainty(R75r, R75r_std, lambda_235=lambda_235):\n    '''\n    calculate 207Pb/235U date uncertainty\n\n    Parameters\n    ----------\n    R75r : float\n        Radiogenic 207Pb/235U ratio\n    R75r_std : float\n        Absolute standard deviation of radiogenic 207Pb/235U ratio\n\n    Returns\n    -------\n    75 age uncertainty in Ma\n    '''\n    if np.any(~np.isfinite(R75r)) or np.any(np.asarray(R75r) < 0) or np.any(~np.isfinite(R75r_std)) or np.any(np.asarray(R75r_std) < 0) or not (np.isfinite(lambda_235) and lambda_235 > 0):\n        raise ValueError(\"Invalid ratio, uncertainty or decay constant\")\n    return 1 / lambda_235 * ( R75r_std / (R75r + 1) ) / 1e6","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1605"},"utils.py:calc_t76_uncertainty":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_t76_uncertainty","line":1624,"code":"def calc_t76_uncertainty(t76, \n                         R76r_std,\n                         lambda_235=lambda_235, lambda_238=lambda_238,\n                         common_U238_U235=common_U238_U235):\n    \n    if not (np.isfinite(t76) and t76 >= 0 and np.isfinite(R76r_std) and R76r_std >= 0):\n        raise ValueError(\"Age and standard uncertainty must be finite and nonnegative\")\n    a, b = lambda_235 * 1e6, lambda_238 * 1e6\n    if not (a > b > 0 and common_U238_U235 > 0):\n        raise ValueError(\"Invalid decay constants or natural U isotope ratio\")\n    if t76 < 0.01:\n        derivative = a/b/common_U238_U235 * ((a-b)/2 + (2*a*a-3*a*b+b*b)*t76/6)\n    else:\n        numerator, denominator = np.expm1(a*t76), np.expm1(b*t76)\n        derivative = (a*np.exp(a*t76)*denominator - b*np.exp(b*t76)*numerator) / denominator**2 / common_U238_U235\n    return R76r_std / abs(derivative)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1624"},"utils.py:calc_t68_Th":{"file":"src/IDTIMS_UPbRPy/utils.py","name":"calc_t68_Th","line":1767,"code":"def calc_t68_Th(R68r, \n                type='D',\n                D_Th_U=None, \n                Pb208r=None, U238s=None, \n                Th_U_magma=None, \n                lambda_238=lambda_238, \n                lambda_230=lambda_230, \n                x0=1e6, tol=1e-8,\n                lambda_232=lambda_232):\n    \n    if type not in ('D', 'magma'):\n        raise ValueError(\"type must be 'D' or 'magma'\")\n\n    if not (np.isfinite(lambda_230) and lambda_230 > 0 and np.isfinite(lambda_238) and lambda_238 > 0 and np.isfinite(lambda_232) and lambda_232 > 0):\n        raise ValueError(\"Decay constants must be finite and positive\")\n\n    if type == 'D':\n        if D_Th_U is None or not np.isfinite(D_Th_U) or D_Th_U < 0:\n            raise ValueError(\"D_Th_U must be finite and nonnegative\")\n        return calc_t68(R68r - lambda_238 / lambda_230 * (D_Th_U - 1), lambda_238)\n\n    else:  # magma\n        # Present-day Th/U derives from 208Pb growth using lambda_232.\n        if not (R68r > 0 and Pb208r >= 0 and U238s > 0 and Th_U_magma > 0):\n            raise ValueError(\"Invalid inputs for magma Th correction\")\n        def residual(t):\n            th_u = Pb208r / np.expm1(lambda_232*t*1e6) / U238s\n            return np.expm1(lambda_238*t*1e6) - R68r + lambda_238/lambda_230*(th_u/Th_U_magma - 1)\n        uncorrected = calc_t68(R68r, lambda_238)\n        lo = max(uncorrected/2, 1e-9)\n        hi = max(uncorrected*2, 1.0)\n        return brentq(residual, lo, hi, xtol=tol/1e6)","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/utils.py#L1767"},"UPbR.py:assign_measurements":{"file":"src/IDTIMS_UPbRPy/UPbR.py","name":"assign_measurements","line":126,"code":"def assign_measurements(UPb_grain, df_row,\n                        Pb_R45m = '204Pb/205Pb Mean',\n                        Pb_R45m_std_rel = '204Pb/205Pb % Standard Error',\n                        Pb_R46m = '204Pb/206Pb Mean',\n                        Pb_R46m_std_rel = '204Pb/206Pb % Standard Error',\n                        Pb_R64m = '206Pb/204Pb Mean',\n                        Pb_R64m_std_rel = '206Pb/204Pb % Standard Error',\n                        Pb_R65m = '206Pb/205Pb Mean',\n                        Pb_R65m_std_rel = '206Pb/205Pb % Standard Error',\n                        Pb_R67m = '206Pb/207Pb Mean',\n                        Pb_R67m_std_rel = '206Pb/207Pb % Standard Error',\n                        Pb_R75m = '207Pb/205Pb Mean',\n                        Pb_R75m_std_rel = '207Pb/205Pb % Standard Error',\n                        Pb_R76m = '207Pb/206Pb Mean',\n                        Pb_R76m_std_rel = '207Pb/206Pb % Standard Error',\n                        Pb_R85m = '208Pb/205Pb Mean',\n                        Pb_R85m_std_rel = '208Pb/205Pb % Standard Error',\n                        U_R85m = '238U/235U Mean',\n                        U_R85m_std_rel = '238U/235U % Standard Error',\n                        U_R35m = '233U/235U Mean',\n                        U_R35m_std_rel = '233U/235U % Standard Error',\n                        U_R83m = '238U/233U Mean',\n                        U_R83m_std_rel = '238U/233U % Standard Error'):\n    UPb_grain.Pb_R45m = df_row[Pb_R45m]\n    UPb_grain.Pb_R45m_std = df_row[Pb_R45m] * df_row[Pb_R45m_std_rel] / 100\n    UPb_grain.Pb_R46m = df_row[Pb_R46m]\n    UPb_grain.Pb_R46m_std = df_row[Pb_R46m] * df_row[Pb_R46m_std_rel] / 100\n    UPb_grain.Pb_R64m = df_row[Pb_R64m]\n    UPb_grain.Pb_R64m_std = df_row[Pb_R64m] * df_row[Pb_R64m_std_rel] / 100\n    UPb_grain.Pb_R65m = df_row[Pb_R65m]\n    UPb_grain.Pb_R65m_std = df_row[Pb_R65m] * df_row[Pb_R65m_std_rel] / 100\n    UPb_grain.Pb_R67m = df_row[Pb_R67m]\n    UPb_grain.Pb_R67m_std = df_row[Pb_R67m] * df_row[Pb_R67m_std_rel] / 100\n    UPb_grain.Pb_R75m = df_row[Pb_R75m]\n    UPb_grain.Pb_R75m_std = df_row[Pb_R75m] * df_row[Pb_R75m_std_rel] / 100\n    UPb_grain.Pb_R76m = df_row[Pb_R76m]\n    UPb_grain.Pb_R76m_std = df_row[Pb_R76m] * df_row[Pb_R76m_std_rel] / 100\n    UPb_grain.Pb_R85m = df_row[Pb_R85m]\n    UPb_grain.Pb_R85m_std = df_row[Pb_R85m] * df_row[Pb_R85m_std_rel] / 100\n    UPb_grain.Pb_R84m = UPb_grain.Pb_R85m / UPb_grain.Pb_R45m\n    UPb_grain.Pb_R84m_std = np.sqrt((UPb_grain.Pb_R85m_std / UPb_grain.Pb_R45m)**2 + (UPb_grain.Pb_R85m / UPb_grain.Pb_R45m**2 * UPb_grain.Pb_R45m_std)**2 )\n    \n    UPb_grain.U_R85m = df_row[U_R85m]\n    UPb_grain.U_R85m_std = df_row[U_R85m] * df_row[U_R85m_std_rel] / 100\n    UPb_grain.U_R35m = df_row[U_R35m]\n    UPb_grain.U_R35m_std = df_row[U_R35m] * df_row[U_R35m_std_rel] / 100\n    UPb_grain.U_R83m = df_row[U_R83m]\n    UPb_grain.U_R83m_std = df_row[U_R83m] * df_row[U_R83m_std_rel] / 100","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/UPbR.py#L126"},"UPb_grain.py:calc_all":{"file":"src/IDTIMS_UPbRPy/UPb_grain.py","name":"calc_all","line":1129,"code":"    def calc_all(self):\n        if self.spike_type != 535:\n            raise NotImplementedError(\"Raw reduction supports 535 tracers only\")\n        from .quality import check_grain_measurements\n        check_grain_measurements(self)\n        for name, value in getattr(self, '_initial_Pb_composition', {}).items():\n            setattr(self, name, value)\n        self.calc_Pb_blank_AWS()\n        self.calc_Pb_partitioning()\n\n        self.Pb206s_partials()\n        self.Pb207s_partials()\n        self.Pb204c_partials()\n\n        self.Pb_covariance_squared()\n\n        self.calc_Pb206s()\n        self.prop_Pb206s_uncertainty()\n\n        self.calc_Pb207s()\n        self.prop_Pb207s_uncertainty()\n\n        self.calc_Pb204c()\n        self.prop_Pb204c_uncertainty()\n\n        self.prop_cov_Pb_Rs_squared()\n        self.calc_all_Pb_Rs_uncertainty()\n\n        self.calc_PbPb_Rs()\n        self.calc_PbPbs_rhos()\n\n\n        self.Pb206r_partials()\n        self.Pb207r_partials()\n        self.Pb208r_partials()\n\n        self.calc_Pb206r()\n        self.prop_Pb206r_uncertainty()\n\n        self.calc_Pb207r()\n        self.prop_Pb207r_uncertainty()\n\n        self.calc_Pb208r()\n        self.prop_Pb208r_uncertainty()\n\n        self.calc_rad_Pb()\n        self.calc_Pbr_Pbc()\n\n        self.calc_R76r()\n        self.prop_cov_R76r_squared()\n        self.calc_Pb_Rr_uncertainty()\n\n        self.calc_U_blank_AW()\n        self.calc_U238b()\n\n        self.U_covariance_squared()\n        self.FU_partials()\n        self.calc_FU()\n        self.prop_FU_uncertainty()\n\n        self.U238s_partials()\n        self.U235s_partials()\n\n        self.calc_U238s()\n        self.prop_U238s_uncertainty()\n\n        self.calc_U235s()\n        self.prop_U235s_uncertainty()\n\n        self.calc_UPb_Rs()\n        self.calc_all_UPb_Rs_uncertainty()\n        self.calc_UPbs_rhos()\n\n        self.calc_UPb_Rr()\n        self.calc_all_UPb_Rr_uncertainty()\n        self.calc_UPbr_rhos()\n\n        from .uncertainty import propagate\n        propagate(self)\n\n        self.calc_t75()\n        self.calc_t68()\n        self.calc_t76()\n\n        self.calc_t75_uncertainty()\n        self.calc_t68_uncertainty()\n        self.calc_t76_uncertainty()\n\n        self.calc_rad_U()\n        self.calc_total_U_ppm()\n        self.calc_total_Pb_ppm()\n\n        if self.Th230_correction_type is not None:\n            # if we are doing Th corrections\n            # first calculate Pb208r related values\n            self.calc_Th_corrections()\n            self.calc_Th232s()\n            self.calc_Th_ppm()\n            self.calc_Pb206r_Th()\n            from .uncertainty import propagate_th\n            propagate_th(self)\n            self.calc_t76_Th_corr()\n            self.t68_Th_corr_std = calc_t68_uncertainty(self.R68r_Th, self.R68r_Th_std, self.lambda_238)\n            self.t76_Th_corr_std = calc_t76_uncertainty(self.t76_Th_corr, self.R76r_Th_std,\n                self.lambda_235, self.lambda_238, self.common_U238_U235)\n        else:\n            self.calc_Th_corrections()\n            self.Pb206r_Th = self.Pb206r\n            self.R68r_Th, self.R68r_Th_std = self.R68r, self.R68r_std\n            self.R76r_Th, self.R76r_Th_std = self.R76r, self.R76r_std","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/UPb_grain.py#L1129"},"constants.py":{"file":"src/IDTIMS_UPbRPy/constants.py","name":"","line":1,"code":"AWPb204=203.973037\nAWPb206=205.974455 \nAWPb207=206.975885 \nAWPb208=207.976641\nAWTh232=232.03805\nAWU238=238.0507882\nU238_rel=0.992747\nAWU235=235.0439299\nU235_rel=0.0072527\n\n# decay constants (y⁻¹)\n\nlambda_235 = 9.8485e-10 # decay constant for U235, y-1\nlambda_235_std = lambda_235 * 0.14 / 100 / 2 \n\nlambda_238 = 1.55125e-10 # decay constant for U238, y-1\nlambda_238_std = lambda_238 * 0.11 / 100 / 2\n\nlambda_232 = 4.94752E-11  # decay constant for Th232, y-1\nlambda_232_std = lambda_232 * 0.5 / 100 / 2\n\nlambda_230 = 9.195e-6 # decay constant for Th230, y-1\n\n# common ratios\ncommon_U238_U235 = 137.818  # natural ratio of U238 to U235 in zircons","url":"https://github.com/duserzym/IDTIMS_UPbRPy/blob/ba1bd2a92f7bbbab0c8b5006b71c32bfecb2ec13/src/IDTIMS_UPbRPy/constants.py#L1"}}};
